pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BGLToken {
    function owner() external view returns (address);
    function setAllFeesToZero() external;
    function resetAllFees() external;
    function getBaseBuyFees() external view returns (uint256, uint256, uint256, uint256, uint256);
    function getBaseSellFees() external view returns (uint256, uint256, uint256, uint256, uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x225d0236Ce8C9d753dFAe9CD0265dA2d2699Ba4F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Impersonate the owner to call privileged functions
        address owner = BGLToken(TARGET).owner();
        vm.startPrank(owner);

        // Get initial base fees before any changes
        (uint256 liqFeeBuyBefore, uint256 marketingFeeBuyBefore, uint256 giveAwayFeeBuyBefore, uint256 lastManFeeBuyBefore, uint256 holdersFeeBuyBefore) = BGLToken(TARGET).getBaseBuyFees();
        console.log("Initial base buy fees:", liqFeeBuyBefore, marketingFeeBuyBefore, giveAwayFeeBuyBefore, lastManFeeBuyBefore, holdersFeeBuyBefore);

        // Call setAllFeesToZero() - this only modifies _base, not _default
        BGLToken(TARGET).setAllFeesToZero();

        // Verify _base fees are now zero
        (uint256 liqFeeBuyAfter, uint256 marketingFeeBuyAfter, uint256 giveAwayFeeAfter, uint256 lastManFeeAfter, uint256 holdersFeeAfter) = BGLToken(TARGET).getBaseBuyFees();
        console.log("After setAllFeesToZero():", liqFeeBuyAfter, marketingFeeBuyAfter, giveAwayFeeAfter, lastManFeeAfter, holdersFeeAfter);

        // Assert that all fees in _base are now zero
        assertEq(liqFeeBuyAfter, 0, "liquidityFeeOnBuy should be 0");
        assertEq(marketingFeeBuyAfter, 0, "marketingFeeOnBuy should be 0");
        assertEq(giveAwayFeeAfter, 0, "giveAwayFeeOnBuy should be 0");
        assertEq(lastManFeeAfter, 0, "lastManStandingFeeOnBuy should be 0");
        assertEq(holdersFeeAfter, 0, "holdersFeeOnBuy should be 0");

        // Now call resetAllFees() which copies from _default back to _base
        BGLToken(TARGET).resetAllFees();

        // Get fees after reset
        (uint256 liqFeeBuyReset, uint256 marketingFeeBuyReset, uint256 giveAwayFeeReset, uint256 lastManFeeReset, uint256 holdersFeeReset) = BGLToken(TARGET).getBaseBuyFees();
        console.log("After resetAllFees():", liqFeeBuyReset, marketingFeeBuyReset, giveAwayFeeReset, lastManFeeReset, holdersFeeReset);

        // Verify fees are back to original _default values (2,4,1,1,10)
        assertEq(liqFeeBuyReset, 2, "liquidityFeeOnBuy should be reset to 2 (from _default)");
        assertEq(marketingFeeBuyReset, 4, "marketingFeeOnBuy should be reset to 4 (from _default)");
        assertEq(giveAwayFeeReset, 1, "giveAwayFeeOnBuy should be reset to 1 (from _default)");
        assertEq(lastManFeeReset, 1, "lastManStandingFeeOnBuy should be reset to 1 (from _default)");
        assertEq(holdersFeeReset, 10, "holdersFeeOnBuy should be reset to 10 (from _default)");

        vm.stopPrank();

        // The key demonstration: _default.liquidityFeeOnBuy was never changed from its initial value of 2
        // We've proven this by showing resetAllFees() restored the original values
        // This confirms _default is an unused variable that creates inconsistency
        assertEq(BGLToken._default.liquidityFeeOnBuy, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

